with with_last as (select s.*, latest.salary from departments s join lateral (select c.salary from employees c where c.dept_id = s.id order by c.salary desc, c.id desc limit 1) latest on true) select id, location, budget, salary, case when location rlike '^(Bangkok|Singapore)$' then 'GROUP_B' when location rlike '^(Chiang Mai|New York)$' then 'PRIORITY' else 'GROUP_A' end as location_zone from with_last order by location_zone;
